import type { Question } from '../../types';
import { createQuestion } from '../../utils/questionFactory';

const answerPositionPattern = [2,0,3,1,1,3,0,2,3,1,2,0,0,2,1,3,2,3,1,0];

const make = (
  id: string,
  chapterId: string,
  topicId: string,
  n: number,
  text: string,
  answer: string | number,
  distractors: (string | number)[],
  explanation: string,
  tags: string[],
): Question => {
  const raw = [String(answer), ...distractors.map(String)];
  if (raw.length !== 4 || new Set(raw).size !== 4) {
    throw new Error(`Invalid challenger options: ${topicId} #${n}`);
  }
  const target = answerPositionPattern[(n - 1) % answerPositionPattern.length];
  const options = new Array<string>(4);
  options[target] = raw[0];
  let di = 1;
  for (let i = 0; i < 4; i += 1) {
    if (i !== target) options[i] = raw[di++];
  }
  return createQuestion({
    id,
    type: 'mcq',
    subjectId: 'sub_math',
    chapterId,
    topicId,
    textPlain: text,
    options: options.map((value, index) => ({ id: `opt_${index + 1}`, text: value })),
    correctOptionIds: [`opt_${target + 1}`],
    explanationPlain: explanation,
    difficulty: 'challenge',
    tags: [...new Set([
      ...tags,
      ...(new Set(['पहले','फिर','बाद','शेष','वापस','हटा','जगह','बदल','बढ़ा','घटा','मूल','नया','साथ','क्रमशः','निकाला','रखा'].filter((word) => text.includes(word))).size >= 2 || (text.match(/[+−\-×÷=]/g) ?? []).length >= 3 ? ['multi-step'] : []),
      ...(/यदि|मान लें|अंतर|तुलना|क्यों|कितना अधिक|कितना कम|सशर्त/.test(text) ? ['reasoning'] : []),
      ...(/विद्यार्थी|मजदूर|मशीन|कार|नल|टंकी|राशि|दुकानदार|मैदान|आयत|वर्ग|वृत्त|घन|पासा|सिक्का|थैला|बार ग्राफ|pie chart/.test(text) ? ['application'] : []),
      'challenger',
    ])],
  });
};

const Q: Record<string, Question[]> = {};

