Q.top_math_01_04 = [
  make("q_math_adv_04_001","chap_math_01","top_math_01_04",1,"यदि (2^x × 4^2) ÷ 8 = 2^6, तो x का मान क्या होगा?","5",["4","6","7"],"4²=2⁴ और 8=2³, इसलिए घात x+4−3=x+1=6; अतः x=5।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_002","chap_math_01","top_math_01_04",2,"[(3^5 ÷ 3^2) × 9] ÷ 27 + 3^2 का मान क्या होगा?","18",["12","15","21"],"9=3² और27=3³। पहला भाग=3^(5−2+2−3)=3²=9; फिर9+9=18।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_003","chap_math_01","top_math_01_04",3,"A=2^5×5^3 है। यदि A को10^2 से भाग देकर फिर8 घटाएँ, तो परिणाम क्या होगा?","32",["24","36","40"],"A=32×125=4000; 10²=100, इसलिएA/100=40; 40−8=32।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_004","chap_math_01","top_math_01_04",4,"(2^7−2^5) ÷ 2^4 + 3^2 का मान क्या होगा?","15",["13","17","21"],"2^5(4−1)=3×32=96; 96÷16=6; 6+9=15।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_005","chap_math_01","top_math_01_04",5,"यदि 5^x×25=5^8, तो 5^x÷25 का मान क्या होगा?","625",["125","525","725"],"25=5², इसलिए x=6। फिर5^x÷25=5^(6−2)=5⁴=625।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_006","chap_math_01","top_math_01_04",6,"(2^6+2^6) ÷ 2^3 + 2^4 का मान क्या होगा?","32",["24","30","40"],"2×2⁶=2⁷; 2⁷÷2³=2⁴=16; फिर16+16=32।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_007","chap_math_01","top_math_01_04",7,"यदि a=2^4 और b=2^7, तो (a²+b)÷2^6 का मान क्या है?","6",["4","5","8"],"a²=2^8 और b=2^7; (2^8+2^7)/2^6=4+2=6।",["x","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_008","chap_math_01","top_math_01_04",8,"N=10^6−3×10^5 है। N को10^4 से भाग देकर उसमें9 जोड़ने पर क्या मिलेगा?","79",["70","89","69"],"N=700000। N÷10000=70 और70+9=79।",["exponents","multi-step","reasoning","challenger"]),
  make("q_math_adv_04_009","chap_math_01","top_math_01_04",9,"यदि 2^x×4^2=2^10 और 8^y=64, तो x+y का मान क्या होगा?","8",["6","7","9"],"4²=2⁴, इसलिएx=6। 8^y=2^6 सेy=2; x+y=8।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_010","chap_math_01","top_math_01_04",10,"[(5^3×5^4) ÷ (5^2×25)] ÷ 5 का मान क्या होगा?","25",["5","15","125"],"25=5²; पहला भाग5^(3+4−2−2)=5³=125; 125÷5=25।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_011","chap_math_01","top_math_01_04",11,"यदि10^(n+1)÷10^3=10^4, तो n का मान निकालकर 2^(n−1)+n का मान क्या होगा?","38",["34","42","40"],"n+1−3=4 सेn=6। इसलिए2^5+6=32+6=38।",["exponents","equation","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_012","chap_math_01","top_math_01_04",12,"(4^4×2^3) ÷ 8^3 + 2^2 का मान क्या होगा?","8",["6","10","12"],"4⁴=2⁸ और8³=2⁹; कुल2²=4। फिर4+4=8।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_013","chap_math_01","top_math_01_04",13,"यदि 27^x=3^12 और 9^y=3^6, तो 2^x+y का मान क्या होगा?","19",["16","17","21"],"27=3³ सेx=4; 9=3² सेy=3। इसलिए2^x+y=2⁴+3=19।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_014","chap_math_01","top_math_01_04",14,"2^8+2^7−2^6 को 2^6 के रूप में factor करने के बाद उसका संख्यात्मक मान क्या होगा?","320",["192","256","384"],"2^6(4+2−1)=5×2^6=5×64=320।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_015","chap_math_01","top_math_01_04",15,"यदि(3^x×3^2)=3^7 और9^y=3^6, तो x−y निकालकर 3^(x−y)+y का मान क्या होगा?","12",["10","11","14"],"x+2=7 सेx=5 और2y=6 सेy=3। इसलिएx−y=2 और3²+3=12।",["exponents","equation","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_016","chap_math_01","top_math_01_04",16,"[(2^7−2^4) ÷ 2^4]^2 + 2^3 का मान क्या होगा?","57",["49","55","65"],"कोष्ठक का मान8−1=7; इसलिए7²+8=57।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_017","chap_math_01","top_math_01_04",17,"यदि 25^a×5^b=5^14 और a=3, तो 2^b÷16 का मान क्या होगा?","16",["8","12","32"],"25³=5⁶, इसलिएb=8। तब2⁸÷16=256÷16=16।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_018","chap_math_01","top_math_01_04",18,"(3×10^5+2×10^4) ÷ 10^3 ÷ 2^5 का मान क्या होगा?","10",["5","8","12"],"पहला भाग320 है; 2⁵=32 और320÷32=10।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_019","chap_math_01","top_math_01_04",19,"यदि 2^(x+1)÷2^3=2^6, तो x²−2^x का मान क्या होगा?","-192",["-160","-192","192"],"x+1−3=6 सेx=8। फिरx²−2^x=64−256=−192।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
  make("q_math_adv_04_020","chap_math_01","top_math_01_04",20,"[3^5÷3^2]+[2^6÷2^3] का मान35 है। इस मान में से2^3 घटाकर प्राप्त संख्या को3 से गुणा करें। परिणाम क्या होगा?","81",["72","84","90"],"35−8=27; 27×3=81।",["exponents","laws-of-exponents","reasoning","multi-step","challenger"]),
];

// 05 — प्रत्यक्ष और प्रतिलोम समानुपात
Q.top_math_02_01 = [
  make("q_math_adv_05_001","chap_math_02","top_math_02_01",1,"8 मजदूर 18 दिनों में एक काम पूरा करते हैं। 6 दिन बाद 2 मजदूर चले जाते हैं। बाकी काम पूरा करने में और कितने दिन लगेंगे?","16 दिन",["14 दिन","18 दिन","20 दिन"],"कुल काम=8×18=144 worker-days। पहले 6 दिनों में 48 पूरे हुए; 96 बाकी हैं। 6 मजदूरों से 96÷6=16 दिन और लगेंगे।",["proportion","work","inverse-proportion","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_002","chap_math_02","top_math_02_01",2,"8 मशीनें 6 घंटे में 1440 वस्तुएँ बनाती हैं। पहले 3 घंटे बाद 2 मशीनें बंद हो गईं। कुल 9 घंटे में कितनी वस्तुएँ बनेंगी?","1800",["1680","1920","2160"],"दर=1440/(8×6)=30 वस्तु प्रति machine-hour। पहले3h में720; अगले6h में6×6×30=1080; कुल1800।",["proportion","production","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_003","chap_math_02","top_math_02_01",3,"एक कार 240 km की दूरी तय करती है। पहले 2 घंटे 60 km/h से और शेष दूरी 80 km/h से तय करती है। कुल समय कितना लगेगा?","3.5 घंटे",["3 घंटे","4 घंटे","4.5 घंटे"],"पहले 120 km तय हुए। शेष120 km को80 km/h से1.5 घंटे लगे; कुल3.5 घंटे।",["proportion","speed-distance","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_004","chap_math_02","top_math_02_01",4,"12 पेन की कीमत ₹180 है। कीमत 10% बढ़ने के बाद 15 पेन खरीदे गए और कुल बिल पर 8% छूट मिली। अंतिम भुगतान कितना होगा?","₹227.70",["₹220.50","₹230.40","₹247.50"],"एक पेन ₹15; वृद्धि के बाद ₹16.50। 15 पेन=₹247.50; 8% छूट=₹19.80; भुगतान ₹227.70।",["proportion","percentage","discount","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_005","chap_math_02","top_math_02_01",5,"एक पाइप 6 मिनट में टंकी का 3/8 भाग भरता है। 10 मिनट बाद दूसरा समान पाइप जोड़ दिया गया। टंकी पूरी भरने में कुल कितना समय लगेगा?","13 मिनट",["12 मिनट","14 मिनट","16 मिनट"],"एक पाइप की दर1/16 tank/min है। 10 मिनट में5/8 भरता है;3/8 बचता है। दो पाइप की दर1/8, इसलिए3 मिनट और; कुल13।",["proportion","tank","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_006","chap_math_02","top_math_02_01",6,"9 गायों के लिए चारा20 दिनों का है। यदि8 दिन बाद3 गायें और जोड़ दी जाएँ, तो चारा कुल कितने दिनों में समाप्त होगा?","17 दिन",["15 दिन","18 दिन","20 दिन"],"कुल चारा180 cow-days का है। पहले8 दिनों में9×8=72 cow-days उपयोग हुए;108 बाकी। 12 गायों के लिए108÷12=9 दिन और; कुल17 दिन।",["proportion","inverse-proportion","multi-step","word-problem","challenger"]),
  make("q_math_adv_05_007","chap_math_02","top_math_02_01",7,"5 कारीगर12 दिनों में900 खिलौने बनाते हैं। पहले4 दिन5 कारीगर और अगले8 दिन7 कारीगर काम करें, तो कुल कितने खिलौने बनेंगे?","1140",["1080","1200","1260"],"दर=900/(5×12)=15 खिलौने प्रति कारीगर-दिन। पहले4 दिन300; अगले8 दिन840; कुल1140।",["proportion","direct-proportion","multi-step","challenger"]),
  make("q_math_adv_05_008","chap_math_02","top_math_02_01",8,"एक ट्रेन की यात्रा दूरी540 km है। वह पहले3 घंटे70 km/h और शेष दूरी110 km/h से तय करती है। कुल समय कितना होगा?","6 घंटे",["5 घंटे","6.5 घंटे","7 घंटे"],"पहले210 km; शेष330 km। 330÷110=3 घंटे; कुल6 घंटे।",["proportion","speed-distance","multi-step","challenger"]),
  make("q_math_adv_05_009","chap_math_02","top_math_02_01",9,"4 मशीनें10 घंटे में800 इकाइयाँ बनाती हैं। पहले5 घंटे4 मशीनें चलीं; बाकी उत्पादन8 मशीनों से किया गया। कुल समय कितना लगा?","7.5 घंटे",["7 घंटे","8 घंटे","9 घंटे"],"दर=800/(4×10)=20 इकाई प्रति machine-hour। पहले5 घंटे400 बने; बाकी400 को8×20=160 इकाई/घंटा की दर से2.5 घंटे लगे; कुल7.5 घंटे।",["proportion","production","multi-step","challenger"]),
  make("q_math_adv_05_010","chap_math_02","top_math_02_01",10,"एक मजदूर 8 दिनों में ₹480 कमाता है। उसकी दैनिक दर 25% बढ़ गई। वह नई दर से 15 दिन काम करता है। कुल कमाई कितनी होगी?","₹1125",["₹900","₹1050","₹1200"],"पुरानी दर₹60/दिन; नई दर₹75/दिन; 15×75=₹1125।",["proportion","percentage","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_011","chap_math_02","top_math_02_01",11,"7 मजदूर24 दिनों में काम पूरा करते हैं।9 दिन बाद2 मजदूर चले जाते हैं। काम कुल कितने दिनों में पूरा होगा और मूल योजना की तुलना में कितने दिन अतिरिक्त लगेंगे?","30 दिन और6 दिन",["28 दिन और4 दिन","30 दिन और6 दिन","32 दिन और8 दिन"],"कुल काम168 worker-days। पहले9 दिनों में63;105 बाकी।5 मजदूरों से21 दिन और; कुल30 दिन। मूल24 दिनों से6 दिन अधिक।",["proportion","work","inverse-proportion","multi-step","comparison","challenger"]),
  make("q_math_adv_05_012","chap_math_02","top_math_02_01",12,"एक पाइप8 मिनट में टंकी का2/5 भाग भरता है। 8 मिनट बाद आधी दर वाला दूसरा पाइप जोड़ दिया गया। टंकी पूरी भरने में कुल कितना समय लगेगा?","16 मिनट",["14 मिनट","18 मिनट","20 मिनट"],"पहला पाइप20 मिनट में पूरी टंकी भरता है। 8 मिनट में2/5 भर चुका; शेष3/5 है। दूसरे की दर1/40 और पहले की1/20, संयुक्त3/40 tank/min; शेष3/5 में8 मिनट। कुल16 मिनट।",["proportion","tank","multi-step","challenger"]),
  make("q_math_adv_05_013","chap_math_02","top_math_02_01",13,"एक नक्शे में 3 cm वास्तविक 12 km को दिखाते हैं। 7.5 cm और 4.25 cm के दो रास्तों में कितनी दूरी का अंतर होगा?","13 km",["11 km","14 km","17 km"],"स्केल4 km/cm है। दोनों दूरियाँ30 km और17 km हैं; अंतर13 km।",["proportion","scale","comparison","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_014","chap_math_02","top_math_02_01",14,"एक कार 60 L ईंधन में 480 km चलती है। 750 km के बाद चालक ने 10% ईंधन बचाकर रखा था। उपयोग किए गए ईंधन की मात्रा कितनी थी?","84.375 L",["75 L","90 L","93.75 L"],"750 km के लिए कुल ईंधन=750×60/480=93.75 L। 10% बचा, इसलिए उपयोग=90%=84.375 L।",["proportion","fuel","percentage","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_015","chap_math_02","top_math_02_01",15,"10 विद्यार्थी6 दिनों में1200 किताबें व्यवस्थित करते हैं। पहले2 दिन सभी10 ने काम किया, फिर2 विद्यार्थी चले गए। बाकी किताबें8 विद्यार्थियों को कितने और दिनों में पूरी करनी होंगी?","5 दिन",["4 दिन","6 दिन","8 दिन"],"दर=1200/(10×6)=20 किताब प्रति विद्यार्थी-दिन। पहले2 दिनों में400 किताबें हुईं;800 बाकी। 8 विद्यार्थियों की दर160/दिन, इसलिए800÷160=5 दिन और।",["proportion","work-rate","multi-step","reasoning","challenger"]),
  make("q_math_adv_05_016","chap_math_02","top_math_02_01",16,"एक प्रिंटर 4 मिनट में 96 पृष्ठ छापता है। 3 प्रिंटर 7.5 मिनट चलते हैं, लेकिन अंतिम 1 मिनट में केवल 2 प्रिंटर चलते हैं। कुल कितने पृष्ठ छपेंगे?","516",["480","528","552"],"एक प्रिंटर24 page/min। पहले6.5 मिनट? बेहतर: 3 printers for 6.5 min=468 pages, अंतिम1 min में2 printers=48; कुल516।",["proportion","printing","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_017","chap_math_02","top_math_02_01",17,"एक यात्रा की दूरी20% बढ़ा दी गई और गति25% बढ़ा दी गई। मूल समय की तुलना में नया समय कितने प्रतिशत घटेगा?","4%",["5%","6%","8%"],"समय का नया/पुराना अनुपात=1.20/1.25=0.96; इसलिए समय4% घटता है।",["proportion","inverse-proportion","percentage","reasoning","challenger"]),
  make("q_math_adv_05_018","chap_math_02","top_math_02_01",18,"6 नल 4 घंटे में टंकी भरते हैं। 1.5 घंटे बाद 2 नल बंद हो गए। टंकी भरने में कुल कितना समय लगेगा?","5.25 घंटे",["4.5 घंटे","5 घंटे","6 घंटे"],"कुल काम24 tap-hours। पहले1.5h में9 पूरे;15 बाकी। 4 नल से3.75h और; कुल5.25h।",["proportion","inverse-proportion","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_019","chap_math_02","top_math_02_01",19,"4.5 m कपड़े की कीमत ₹540 है। 2.5 m खरीदा जा चुका है। उसी दर पर कुल 7.25 m के लिए कितनी अतिरिक्त राशि देनी होगी?","₹570",["₹540","₹600","₹625"],"दर₹120/m। 7.25m=₹870; पहले2.5m=₹300; अतिरिक्त₹570।",["proportion","direct-proportion","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_05_020","chap_math_02","top_math_02_01",20,"एक मशीन की उत्पादन दर20% बढ़ती है। पहले5 घंटे में600 इकाइयाँ बनती थीं। नई दर पर900 इकाइयाँ बनाने में कितना समय लगेगा?","6.25 घंटे",["5.75 घंटे","6 घंटे","6.5 घंटे"],"पुरानी दर120 इकाई/घंटा; नई दर144 इकाई/घंटा। 900÷144=6.25 घंटे।",["proportion","percentage","multi-step","reverse","challenger"]),
];

// 06 — राशियों की तुलना
Q.top_math_02_02 = [
  make("q_math_adv_06_001","chap_math_02","top_math_02_02",1,"₹2400 पर पहले15% और फिर10% छूट दी गई। उसी वस्तु पर एकल25% छूट देने की तुलना में ग्राहक कितना अधिक भुगतान करेगा?","₹36",["₹24","₹30","₹48"],"दो छूटों के बाद कीमत=2400×0.85×0.90=1836। एकल25% छूट पर1800। अंतर₹36।",["comparing-quantities","discount","successive-change","comparison","challenger"]),
  make("q_math_adv_06_002","chap_math_02","top_math_02_02",2,"किसी वस्तु की कीमत 20% बढ़ी, फिर नई कीमत पर 20% घटाई गई और अंत में ₹50 का शुल्क जोड़ा गया। मूल कीमत ₹2500 थी। अंतिम भुगतान कितना है?","₹2450",["₹2400","₹2500","₹2550"],"2500×1.20=3000; 20% कमी से2400; ₹50 शुल्क जोड़कर₹2450।",["comparing-quantities","percentage","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_003","chap_math_02","top_math_02_02",3,"अंकित मूल्य₹3200 है और15% छूट के बाद20% लाभ होता है। यदि उसी क्रय मूल्य पर दुकानदार केवल10% छूट दे, तो लाभ प्रतिशत कितना होगा?","32.5%",["25%","35%","40%"],"15% छूट से SP2720 और20% लाभ, इसलिए CP=2720/1.2=6800/3। 10% छूट पर SP2880; लाभ=(2880−6800/3)/(6800/3)×100=32.5%।",["comparing-quantities","discount","profit-loss","reverse","multi-step","challenger"]),
  make("q_math_adv_06_004","chap_math_02","top_math_02_02",4,"CP₹1500 है। 12% लाभ के लक्ष्य से MP तय किया गया और फिर10% छूट दी गई। यदि छूट5% कर दी जाए, तो नया लाभ प्रतिशत क्या होगा?","6.4%",["5.2%","7.6%","8%"],"पहला MP=1680। 5% छूट पर SP=1596; लाभ96, इसलिए96/1500×100=6.4%।",["comparing-quantities","profit-loss","discount","comparison","multi-step","challenger"]),
  make("q_math_adv_06_005","chap_math_02","top_math_02_02",5,"₹5000 पर8% वार्षिक दर से2 वर्ष में SI और CI का अंतर₹32 है। उसी दर पर2 वर्ष का SI कितना होगा?","₹800",["₹640","₹720","₹840"],"2 वर्ष के लिए CI−SI=P×r²=5000×0.08²=₹32। फिर SI=5000×8×2/100=₹800।",["comparing-quantities","interest","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_006","chap_math_02","top_math_02_02",6,"₹4000 पर 5% वार्षिक चक्रवृद्धि ब्याज से 2 वर्ष बाद राशि मिली। उसमें से ₹500 निकालने के बाद बची राशि पर एक और वर्ष 5% ब्याज मिला। अंतिम राशि कितनी हुई?","₹4105.50",["₹3990","₹4200","₹4310"],"2 वर्षों बाद राशि4410। ₹500 निकालने पर3910; एक वर्ष बाद3910×1.05=₹4105.50।",["comparing-quantities","compound-interest","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_007","chap_math_02","top_math_02_02",7,"₹1800 की कीमत25% बढ़ी और नई कीमत पर20% छूट दी गई। यदि अंतिम कीमत पर5% कर भी लगे, तो ग्राहक कितना देगा और मूल कीमत से कितना अधिक होगा?","₹1890 और₹90",["₹1800 और₹0","₹1872 और₹72","₹1920 और₹120"],"नई कीमत2250;20% छूट से1800;5% कर=90; भुगतान1890, जो मूल से₹90 अधिक है।",["comparing-quantities","percentage","discount","tax","multi-step","challenger"]),
  make("q_math_adv_06_008","chap_math_02","top_math_02_02",8,"किसी वस्तु को10% हानि पर₹1440 में बेचा गया। यदि ₹1800 के अंकित मूल्य पर5% छूट देकर बेचा जाए, तो लाभ प्रतिशत कितना होगा?","6.875%",["5%","7.5%","8.75%"],"CP=1440/0.9=1600। नया SP=1800×0.95=1710; लाभ110; 110/1600×100=6.875%。",["comparing-quantities","profit-loss","discount","reverse","multi-step","challenger"]),
  make("q_math_adv_06_009","chap_math_02","top_math_02_02",9,"एक दुकानदार ₹2400 के अंकित मूल्य पर20% छूट देकर20% लाभ कमाता है। यदि वह25% छूट दे, तो लाभ प्रतिशत कितना रह जाएगा?","12.5%",["10%","15%","20%"],"पहले SP=1920;20% लाभ से CP=1600। 25% छूट पर SP=1800; लाभ=200; 200/1600×100=12.5%。",["comparing-quantities","profit-loss","discount","comparison","multi-step","challenger"]),
  make("q_math_adv_06_010","chap_math_02","top_math_02_02",10,"किसी वस्तु की कीमत 30% बढ़ाई, फिर 10% घटाई, फिर ₹16 जोड़े। अंतिम कीमत ₹1420 है। मूल कीमत क्या थी?","₹1200",["₹1100","₹1250","₹1300"],"अंतिम 1.30×0.90x+16=1420 ⇒1.17x=1404 ⇒x=1200।",["comparing-quantities","successive-percentage","reverse","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_011","chap_math_02","top_math_02_02",11,"₹2500 पर 12% वार्षिक साधारण ब्याज से 3 वर्ष में राशि बनी। उस राशि का 20% किसी काम में खर्च कर दिया गया। कितना धन शेष रहा?","₹2720",["₹2600","₹2800","₹2900"],"SI=900, राशि3400। उसका80%=₹2720 बचा।",["comparing-quantities","simple-interest","percentage","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_012","chap_math_02","top_math_02_02",12,"₹2500 पर 12% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज ₹636 है। यदि ब्याज का 1/6 भाग अलग रख दिया जाए, तो शेष ब्याज कितना होगा?","₹530",["₹500","₹540","₹560"],"CI=₹636; उसका1/6=₹106; शेष₹530।",["comparing-quantities","compound-interest","fraction","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_013","chap_math_02","top_math_02_02",13,"किसी वस्तु पर25% लाभ चाहिए और20% छूट देनी है। यदि CP₹2400 है, तो MP और discount amount क्रमशः कितने होंगे?","₹3750 और₹750",["₹3600 और₹720","₹3900 और₹780","₹4000 और₹800"],"लक्ष्य SP=2400×1.25=3000। MP×0.80=3000 ⇒MP=3750; discount=750।",["comparing-quantities","profit-loss","discount","reverse","multi-step","challenger"]),
  make("q_math_adv_06_014","chap_math_02","top_math_02_02",14,"₹1600 की वस्तु पर15% छूट के बाद₹160 लाभ होता है। यदि उसी वस्तु को10% छूट पर बेचा जाए, तो नया लाभ कितना होगा?","₹240",["₹200","₹260","₹280"],"पहली SP=1360 और लाभ160, इसलिए CP=1200। 10% छूट पर SP=1440; नया लाभ240।",["comparing-quantities","profit-loss","discount","comparison","multi-step","challenger"]),
  make("q_math_adv_06_015","chap_math_02","top_math_02_02",15,"एक राशि पर2 वर्ष का CI₹410 और SI₹400 है, दोनों की दर10% है। मूल राशि ज्ञात करके उसी राशि पर8% वार्षिक दर से2 वर्ष का SI निकालें।","₹160",["₹120","₹160","₹200"],"10% पर2 वर्षों मेंCI−SI=P×(10/100)^2=₹10, इसलिएP=₹1000। अब8% पर2 वर्ष काSI=₹160।",["comparing-quantities","interest","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_016","chap_math_02","top_math_02_02",16,"मूल कीमत₹1600 को12% घटाकर फिर25% बढ़ाया गया। अंतिम कीमत मूल कीमत से कितने प्रतिशत अधिक/कम है?","10% अधिक",["8% अधिक","10% कम","12% अधिक"],"1600×0.88×1.25=1760; वृद्धि160/1600=10%।",["comparing-quantities","successive-change","percentage","comparison","challenger"]),
  make("q_math_adv_06_017","chap_math_02","top_math_02_02",17,"एक वस्तु का CP₹3000 है। दुकानदार20% लाभ के लक्ष्य से MP तय करता है और5% छूट देता है। वास्तविक विक्रय मूल्य और वास्तविक लाभ प्रतिशत क्या होगा?","₹3420 और14%",["₹3300 और10%","₹3420 और14%","₹3450 और15%"],"लक्ष्य SP=₹3600, इसलिएMP=₹3600।5% छूट के बादSP=₹3420; लाभ₹420; लाभ%=14%।",["comparing-quantities","profit-loss","discount","multi-step","reasoning","challenger"]),
  make("q_math_adv_06_018","chap_math_02","top_math_02_02",18,"एक दुकानदार10% छूट देकर8% लाभ कमाता है। CP₹1250 है। उसी अंकित मूल्य पर15% छूट देने पर नया लाभ प्रतिशत कितना होगा?","2%",["1%","2%","4%"],"पहलेSP=₹1350;90% MP=₹1350 सेMP=₹1500।15% छूट परSP=₹1275; लाभ₹25; लाभ%=2%।",["comparing-quantities","profit-loss","discount","multi-step","comparison","challenger"]),
  make("q_math_adv_06_019","chap_math_02","top_math_02_02",19,"₹5000 की राशि 2 वर्षों में 20% बढ़ती है, यदि साधारण ब्याज लगाया जाए। वार्षिक दर ज्ञात करें और फिर उसी दर पर 3 वर्षों का SI निकालें।","₹1500",["₹1200","₹1800","₹2000"],"2 वर्षों का SI=₹1000, इसलिए R=10%। 3 वर्षों का SI=5000×10×3/100=₹1500।",["comparing-quantities","simple-interest","reverse","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_06_020","chap_math_02","top_math_02_02",20,"एक वस्तु का अंकित मूल्य ₹5000 है। 15% और फिर 20% छूट दी गई। अंतिम कीमत पर 5% कर लगाया गया। ग्राहक कितना भुगतान करेगा?","₹3570",["₹3400","₹3500","₹3675"],"5000×0.85×0.80=3400; 5% कर=170; कुल₹3570।",["comparing-quantities","discount","tax","multi-step","application","reasoning","multi-step","challenger"]),
];

// 07 — बीजीय व्यंजक और सर्वसमिकाएँ
Q.top_math_03_01 = [
  make("q_math_adv_07_001","chap_math_03","top_math_03_01",1,"यदि x=4 और y=3, तो A=3(2x−y)−2(x+y) है। A+(x−y)^2 का मान क्या होगा?","2",["0","4","6"],"A=1 और(x−y)^2=1; इसलिए कुल2।",["algebra","substitution","identities","multi-step","challenger"]),
  make("q_math_adv_07_002","chap_math_03","top_math_03_01",2,"यदि x=7, तो (x+5)^2+(x−5)^2 का मान क्या होगा?","148",["138","158","168"],"सर्वसमिका से2(x²+5²)=2(49+25)=148।",["algebra","identities","substitution","multi-step","challenger"]),
  make("q_math_adv_07_003","chap_math_03","top_math_03_01",3,"यदि a+b=12 और ab=20, तो [(a+b)^2−2ab]+(a+b) का मान क्या होगा?","116",["104","124","136"],"पहला भाग a²+b²=144−40=104; फिर12 जोड़ने पर116।",["algebra","identities","reasoning","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_004","chap_math_03","top_math_03_01",4,"2x²+9x+4 के गुणनखंड ज्ञात करके x=2 पर उनके गुणनफल का मान क्या होगा?","30",["24","28","36"],"2x²+9x+4=(2x+1)(x+4)। x=2 पर दोनों गुणनखंड 5 और6 हैं; उनका गुणनफल 30।",["algebra","factorisation","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_005","chap_math_03","top_math_03_01",5,"यदि x=5, तो (3x+2)^2+(3x−2)^2 का मान क्या होगा?","458",["438","448","468"],"सर्वसमिका से2[(3x)^2+2^2]=2(225+4)=458।",["algebra","identities","multi-step","challenger"]),
  make("q_math_adv_07_006","chap_math_03","top_math_03_01",6,"यदि x+y=9 और x−y=3, तो [(x+y)^2+(x−y)^2]/2 + xy का मान क्या होगा?","63",["45","54","72"],"पहला भाग(81+9)/2=45। xy=((81−9)/4)=18; कुल63।",["algebra","identities","reasoning","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_007","chap_math_03","top_math_03_01",7,"6x²−18x+12 का पूर्ण गुणनखंडन क्या है?","6(x−1)(x−2)",["6(x−3)(x−2)","3(2x−1)(x−4)","6(x+1)(x+2)"],"पहले 6 सामान्य लें: 6(x²−3x+2); फिर x²−3x+2=(x−1)(x−2)।",["algebra","factorisation","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_008","chap_math_03","top_math_03_01",8,"यदि p−q=5 और pq=14, तो p²+q²+pq का मान क्या होगा?","67",["53","70","81"],"पहले(p+q)²=25+56=81। फिरp²+q²=81−28=53; 53+14=67।",["algebra","identities","reasoning","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_009","chap_math_03","top_math_03_01",9,"यदि a=4 और b=1, तो (2a−3b)^2+(2a+3b)^2 का मान क्या होगा?","146",["124","136","154"],"दोनों पदों का योग=2[(2a)^2+(3b)^2]=2(64+9)=146।",["algebra","identities","substitution","multi-step","challenger"]),
  make("q_math_adv_07_010","chap_math_03","top_math_03_01",10,"x²−13x+40 के गुणनखंड ज्ञात कीजिए। यदि x=13 हो, तो दोनों गुणनखंडों का गुणनफल कितना होगा?","40",["35","48","52"],"गुणनखंड(x−5)(x−8) हैं। x=13 पर8 और5; गुणनफल40।",["algebra","factorisation","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_011","chap_math_03","top_math_03_01",11,"यदि x=−3,y=2, तो [(2x²−3xy+y²)÷(x−y)]²+x का मान क्या होगा?","61",["55","59","65"],"व्यंजक40 और x−y=−5, इसलिए भागफल−8। उसका वर्ग64; x=−3 जोड़ने पर61।",["algebra","substitution","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_012","chap_math_03","top_math_03_01",12,"यदि a+b=11 और ab=24, तो (a+b)^2−3ab+(a−b)^2 का मान क्या होगा?","74",["64","84","96"],"पहला भाग121−72=49। (a−b)^2=121−96=25। कुल74।",["algebra","identities","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_013","chap_math_03","top_math_03_01",13,"यदि 2x+5y=17 और 2x−5y=7, तो x+y का मान क्या होगा?","7",["5","6","8"],"दोनों समीकरण जोड़ने पर4x=24 ⇒x=6। घटाने पर10y=10 ⇒y=1। इसलिएx+y=7।",["algebra","simultaneous-equations","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_014","chap_math_03","top_math_03_01",14,"यदि m+n=11 और mn=24, तो [(m−n)^2+4mn]/(m+n)+mn का मान क्या होगा?","35",["25","30","44"],"ऊपरी अंश=(m+n)²=121; 121/11=11; फिर11+24=35।",["algebra","identities","reasoning","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_015","chap_math_03","top_math_03_01",15,"यदि x=12, तो (x+2)(x−7)+(x−2)(x+7) का मान क्या है?","260",["220","240","280"],"पहला=70, दूसरा=190; योग260।",["x","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_016","chap_math_03","top_math_03_01",16,"यदि a+b=13 और a−b=5, तो (a+b)^2+(a−b)^2 का मान क्या होगा?","194",["184","198","204"],"सीधे दिए दोनों मानों के वर्ग जोड़ें:13²+5²=169+25=194।",["algebra","identities","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_017","chap_math_03","top_math_03_01",17,"x²+13x+36=(x+4)(x+9) है। यदि x=2 हो, तो दोनों गुणनखंडों का गुणनफल कितना होगा?","66",["54","60","72"],"x=2 पर गुणनखंड6 और11; गुणनफल66।",["algebra","factorisation","substitution","multi-step","challenger"]),
  make("q_math_adv_07_018","chap_math_03","top_math_03_01",18,"यदि a−b=7 और a+b=13, तो (a+b)^2−ab का मान क्या होगा?","139",["109","129","169"],"ab=((a+b)²−(a−b)²)/4=(169−49)/4=30; फिर169−30=139।",["algebra","identities","reasoning","multi-step","application","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_019","chap_math_03","top_math_03_01",19,"यदि p=2 और q=3, तो [(3p+4q)^2−(3p−4q)^2]÷p का मान क्या है?","144",["96","120","192"],"अंतर=4(3p)(4q)=48pq=48×2×3=288; p=2 से भाग देने पर144।",["algebra","identities","substitution","reasoning","multi-step","challenger"]),
  make("q_math_adv_07_020","chap_math_03","top_math_03_01",20,"3x²−x−10=(3x+5)(x−2)। यदि x=3, तो व्यंजक का मान क्या होगा?","14",["10","12","16"],"x=3 पर (14)(1)=14।",["x","application","reasoning","multi-step","challenger"]),
];

